// Generated by the /ship test coverage audit.
// background.js exports nothing and calls chrome.* at import time, so these tests drive it the way
// Chrome does: through the listeners it registers. `chrome` and `fetch` are fakes; no production seam.
import test, { mock } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';

const NONE = -1;
const WIN = 1;
const listeners = {};
let tabs, groups, calls, nextGroupId, settled, settings, session;

const live = () => groups.filter((g) => tabs.some((t) => t.groupId === g.id));

globalThis.chrome = {
  storage: {
    local: { get: async () => ({ keys: { anthropic: 'test-key' }, ...settings }) },
    session: {
      get: async (key) => (key in session ? { [key]: session[key] } : {}),
      set: async (items) => Object.assign(session, structuredClone(items)),
      remove: async (key) => delete session[key],
    },
  },
  notifications: {
    onButtonClicked: { addListener: (fn) => (listeners.button = fn) },
    onClosed: { addListener: (fn) => (listeners.closed = fn) },
    create: (id, options) => calls.push(['notify', id, options]),
    clear: (id) => calls.push(['clearNotification', id]),
  },
  runtime: { openOptionsPage: () => calls.push(['openOptionsPage']) },
  action: {
    onClicked: { addListener: (fn) => (listeners.clicked = fn) },
    setBadgeText: ({ text }) => calls.push(['badge', text]),
    setTitle: ({ title }) => {
      calls.push(['title', title]);
      settled?.(); // the last thing regroup does, on success and on failure
    },
  },
  tabGroups: {
    TAB_GROUP_ID_NONE: NONE,
    query: async () => live().map((g) => ({ ...g })),
    update: async (id, props) => {
      Object.assign(groups.find((g) => g.id === id), props);
    },
  },
  tabs: {
    onUpdated: { addListener: (fn) => (listeners.updated = fn) },
    query: async ({ windowId, pinned, active }) =>
      tabs.filter((t) => t.windowId === windowId && (active ? t.active : t.pinned === pinned)).map((t) => ({ ...t })),
    ungroup: async (ids) => {
      // Chrome rejects an empty id list.
      if (ids.length === 0) throw new Error('tabs.ungroup needs at least 1 tab');
      calls.push(['ungroup', [...ids].sort()]);
      tabs.forEach((t) => ids.includes(t.id) && (t.groupId = NONE));
    },
    group: async ({ tabIds, groupId }) => {
      const id = groupId ?? nextGroupId++;
      if (groupId === undefined) groups.push({ id, title: '' });
      tabs.forEach((t) => tabIds.includes(t.id) && (t.groupId = id));
      return id;
    },
  },
};

const tab = (id, groupId = NONE, extra = {}) => ({ id, windowId: WIN, pinned: false, groupId, title: `Tab ${id}`, url: `https://site${id}.example/`, ...extra });

// Tabs 1 and 2 sit in the hand-made group "Old" (id 7); 3 and 4 are loose; 5 is pinned; 6 is not a web page.
function reset() {
  tabs = [tab(1, 7), tab(2, 7), tab(3), tab(4), tab(5, NONE, { pinned: true }), tab(6, 7, { url: 'chrome://settings/' })];
  groups = [{ id: 7, title: 'Old', collapsed: true }];
  calls = [];
  nextGroupId = 100;
  settings = { rename: 'auto' }; // most tests want the plan applied at once; the asking tests set 'ask' themselves
  session = {};
}

// Fake AI provider. `reply` is the plan object, or a function for a custom response. Returns the prompts sent.
function stubAI(reply, { status = 200, whileWaiting = () => {} } = {}) {
  const prompts = [];
  globalThis.fetch = async (url, init) => {
    prompts.push(JSON.parse(init.body).messages[0].content);
    whileWaiting();
    const text = typeof reply === 'string' ? reply : JSON.stringify(reply);
    return { ok: status < 400, status, statusText: 'x', json: async () => (status < 400 ? { content: [{ type: 'text', text }] } : { error: { message: 'boom' } }) };
  };
  return prompts;
}

const groupOf = (id) => tabs.find((t) => t.id === id).groupId;
const titleOf = (id) => groups.find((g) => g.id === groupOf(id))?.title;
const ungroupCalls = () => calls.filter((c) => c[0] === 'ungroup');
const lastBadge = () => calls.filter((c) => c[0] === 'badge').at(-1)?.[1];
const click = () => listeners.clicked({ windowId: WIN });

await import('../background.js');

// Value: protects=a toolbar click sends no existing group names and dissolves old groups before applying the AI plan;
//   fails_when=a full regroup sends group names again, skips the ungroup, or ungroups after grouping;
//   why_new=no test imports background.js; grouping/ai tests cover only the pure helpers; seam=none;
//   no_claim=real Chrome tab-group behavior (chrome.* and the AI provider are in-memory fakes)
test('full regroup ignores existing groups and rebuilds from scratch', async () => {
  reset();
  // "Old" with one tab would be allowed if the AI had been told "Old" exists; from scratch it is dropped.
  const prompts = stubAI({ groups: [{ name: 'Old', tabs: [0] }, { name: 'Dev', tabs: [1, 2] }] });
  await click();

  assert.match(prompts[0], /^Existing groups: \[\]\n/);
  assert.deepEqual(ungroupCalls(), [['ungroup', [1, 2, 3, 4]]]); // not the pinned tab, not chrome://
  assert.equal(groupOf(1), NONE);
  assert.equal(titleOf(2), 'Dev');
  assert.equal(groupOf(2), groupOf(3));
  assert.notEqual(groupOf(2), 7);
  assert.equal(groupOf(4), NONE);
  assert.equal(groupOf(6), 7);
  assert.equal(lastBadge(), '');
});

// Value: protects=a failed or unreadable AI reply on a full regroup leaves every existing group as it was;
//   fails_when=the ungroup moves before the AI call or before the reply is parsed;
//   why_new=no existing test reaches regroup(); seam=none;
//   no_claim=real provider errors and timeouts (fetch is a fake returning 500 or non-JSON text)
test('full regroup keeps the old groups when the AI call fails', async (t) => {
  t.mock.method(console, 'error', () => {});
  for (const stub of [() => stubAI({}, { status: 500 }), () => stubAI('sorry, I cannot')]) {
    reset();
    stub();
    await click();
    assert.deepEqual(ungroupCalls(), []);
    assert.deepEqual([1, 2, 3, 4].map(groupOf), [7, 7, NONE, NONE]);
    assert.equal(lastBadge(), '!');
  }
});

// Value: protects=new groups start collapsed except the one holding the tab in view, and a group that already existed keeps its state;
//   fails_when=new groups are left expanded, the active tab's group is collapsed, or joining an existing group changes its collapsed state;
//   why_new=no test reads the collapsed flag; seam=none;
//   no_claim=how real Chrome reacts to collapsing (the flag is only recorded by the fake)
test('new groups are collapsed unless they hold the active tab; existing groups are left alone', async () => {
  reset();
  tabs.find((t) => t.id === 3).active = true;
  stubAI({ groups: [{ name: 'Docs', tabs: [0, 1] }, { name: 'Dev', tabs: [2, 3] }] });
  await click();
  assert.equal(groups.find((g) => g.title === 'Docs').collapsed, true);
  assert.equal(groups.find((g) => g.title === 'Dev').collapsed, false);

  // A group the user had open before a full regroup: the new group its tabs land in stays open, the rest collapse.
  reset();
  groups[0].collapsed = false;
  tabs.find((t) => t.id === 5).active = true; // the pinned tab, so no planned group holds the active tab
  stubAI({ groups: [{ name: 'Mixed', tabs: [0, 2] }, { name: 'Rest', tabs: [1, 3] }] });
  await click();
  assert.equal(groups.find((g) => g.title === 'Mixed').collapsed, false); // tab 1 came from the open group
  assert.equal(groups.find((g) => g.title === 'Rest').collapsed, false); // tab 2 came from it too
  reset();
  groups[0].collapsed = false;
  tabs.find((t) => t.id === 5).active = true;
  stubAI({ groups: [{ name: 'WasOpen', tabs: [0, 1] }, { name: 'Loose', tabs: [2, 3] }] });
  await click();
  assert.equal(groups.find((g) => g.title === 'WasOpen').collapsed, false);
  assert.equal(groups.find((g) => g.title === 'Loose').collapsed, true);

  // Automatic placement into a group the user has open must not collapse it.
  reset();
  tabs = [tab(1, 7), tab(2, 7), tab(3)];
  groups[0].collapsed = false;
  stubAI({ groups: [{ name: 'Old', tabs: [0] }] });
  mock.timers.enable({ apis: ['setTimeout'] });
  const done = new Promise((resolve) => (settled = resolve));
  listeners.updated(3, { status: 'complete' }, tab(3));
  mock.timers.tick(20000);
  await done;
  mock.timers.reset();
  assert.equal(groupOf(3), 7);
  assert.equal(groups[0].collapsed, false);
});

// Value: protects=a full regroup whose AI plan has no usable group dissolves nothing and shows the "!" badge;
//   fails_when=the ungroup runs before the plan is checked, so an empty or all-singleton reply wipes every group silently;
//   why_new=the failure test covers thrown errors only, an empty plan parses fine; seam=none;
//   no_claim=how often a real provider returns an empty plan (the reply is a fake)
test('full regroup keeps the old groups when the AI plan is empty', async (t) => {
  t.mock.method(console, 'error', () => {});
  for (const plan of [{ groups: [] }, { groups: [{ name: 'Solo', tabs: [0] }] }]) {
    reset();
    stubAI(plan);
    await click();
    assert.deepEqual(ungroupCalls(), []);
    assert.deepEqual([1, 2, 3, 4].map(groupOf), [7, 7, NONE, NONE]);
    assert.equal(lastBadge(), '!');
  }
});

// Value: protects=a second click while a full regroup is running does not start another paid call or a second dissolve;
//   fails_when=the busy branch queues a full run behind a full run again;
//   why_new=no test clicks twice before the first run settles; seam=none;
//   no_claim=real click timing and key auto-repeat (both clicks are fired in the same tick)
test('a second click during a full regroup is ignored', async () => {
  reset();
  const prompts = stubAI({ groups: [{ name: 'Dev', tabs: [0, 1] }] });
  const first = click();
  await click();
  await first;
  await new Promise((resolve) => setImmediate(resolve)); // let any wrongly queued run start
  assert.equal(prompts.length, 1);
  assert.equal(ungroupCalls().length, 1);
});

// Value: protects=a full regroup only touches tabs still in the window when the reply arrives, and none if all are gone;
//   fails_when=ungroup is called with closed tab ids, or with an empty list (Chrome rejects it and the badge shows "!");
//   why_new=no existing test reaches regroup(); seam=none;
//   no_claim=real tab-close timing (the fake removes tabs inside the fetch stub)
test('full regroup copes with tabs closed while the AI was thinking', async () => {
  reset();
  stubAI({ groups: [{ name: 'Old', tabs: [0, 1, 2] }] }, { whileWaiting: () => (tabs = tabs.filter((t) => t.id !== 2)) });
  await click();
  assert.deepEqual(ungroupCalls(), [['ungroup', [1, 3, 4]]]);
  assert.equal(titleOf(1), 'Old');
  assert.equal(groupOf(1), groupOf(3));
  assert.notEqual(groupOf(1), 7); // a fresh group, even when the AI reuses an old name

  reset();
  stubAI({ groups: [{ name: 'Dev', tabs: [0, 1] }] }, { whileWaiting: () => (tabs = []) });
  await click();
  assert.deepEqual(ungroupCalls(), []);
  assert.equal(lastBadge(), '');
});

// Value: protects=a toolbar click with fewer than two web tabs makes no AI call and changes nothing;
//   fails_when=the early-return guard is dropped or reordered after the ungroup, so one lone tab costs a call or loses its group;
//   why_new=no existing test reaches regroup(); seam=none;
//   no_claim=none beyond protects (chrome.* is an in-memory fake)
test('full regroup with a single web tab does nothing', async () => {
  reset();
  tabs = [tab(1, 7), tab(5, NONE, { pinned: true })];
  const prompts = stubAI({ groups: [] });
  await click();
  assert.deepEqual(prompts, []);
  assert.deepEqual(calls, []);
  assert.equal(groupOf(1), 7);
});

// Value: protects=automatic placement still tells the AI the existing group names, joins that group and dissolves nothing;
//   fails_when=the from-scratch behavior leaks into the automatic path (names dropped, tabs ungrouped, or a duplicate group made);
//   why_new=no existing test reaches regroup(); seam=none;
//   no_claim=the debounce timing and service-worker lifetime (setTimeout is mocked)
test('automatic placement still joins existing groups and never ungroups', async () => {
  reset();
  tabs = [tab(1, 7), tab(2, 7), tab(3)];
  const prompts = stubAI({ groups: [{ name: 'Old', tabs: [0] }] });
  mock.timers.enable({ apis: ['setTimeout'] });
  const done = new Promise((resolve) => (settled = resolve));
  listeners.updated(3, { status: 'complete' }, tab(3));
  mock.timers.tick(20000);
  await done;
  mock.timers.reset();

  assert.match(prompts[0], /^Existing groups: \["Old"\]\nTabs:\n0 \| Tab 3 /);
  assert.deepEqual(ungroupCalls(), []);
  assert.deepEqual([1, 2, 3].map(groupOf), [7, 7, 7]);
  assert.equal(live().length, 1);
});

// Fires the automatic path for one freshly loaded tab and waits for the run to finish.
async function loadTab(t) {
  mock.timers.enable({ apis: ['setTimeout'] });
  const done = new Promise((resolve) => (settled = resolve));
  listeners.updated(t.id, { status: 'complete' }, t);
  mock.timers.tick(20000);
  await done;
  mock.timers.reset();
}

// Value: protects=the rename setting decides what happens to an AI rename proposal: ask shows a notification and changes nothing, auto renames, keep ignores it;
//   fails_when=a group is renamed without the user's choice in ask or keep mode, or auto mode drops the proposal;
//   why_new=no test sends a "rename" field through regroup; seam=none;
//   no_claim=how Chrome renders the notification and its buttons (notifications is a recording fake)
test('a rename proposal follows the rename setting', async () => {
  const plan = { groups: [{ name: 'Old', tabs: [0], rename: 'Wider' }] };
  for (const [mode, title, notified] of [[undefined, 'Old', 1], ['ask', 'Old', 1], ['auto', 'Wider', 0], ['keep', 'Old', 0]]) {
    reset();
    // A distinct title per round: an unchanged tab list is deliberately not sent to the AI twice.
    const fresh = tab(3, NONE, { title: `Rename round ${mode}` });
    tabs = [tab(1, 7), tab(2, 7), fresh];
    settings = mode ? { rename: mode } : {};
    stubAI(plan);
    await loadTab(fresh);
    assert.equal(groupOf(3), 7, mode);
    assert.equal(groups[0].title, title, mode);
    assert.equal(calls.filter((c) => c[0] === 'notify').length, notified, mode);
  }
});

// Value: protects=the notification's first button renames the group it was asked about and the second leaves it alone, also for names holding the id separator;
//   fails_when=the button index is read the wrong way round, the name is cut at a separator, or a closed group makes the click throw;
//   why_new=no test clicks a notification button; seam=none;
//   no_claim=that Chrome delivers the click after the worker was stopped (the listener is called directly)
test('the rename notification buttons rename or keep', async () => {
  reset();
  settings = {}; // the default is 'ask'
  const fresh = tab(3, NONE, { title: 'Button round' });
  tabs = [tab(1, 7), tab(2, 7), fresh];
  stubAI({ groups: [{ name: 'Old', tabs: [0], rename: 'A|B' }] });
  await loadTab(fresh);
  const [, id, options] = calls.find((c) => c[0] === 'notify');
  assert.match(options.buttons[0].title, /A\|B/);

  await listeners.button(id, 1);
  assert.equal(groups[0].title, 'Old');
  await listeners.button(id, 0);
  assert.equal(groups[0].title, 'A|B');

  await listeners.button('rename|999|Gone', 0); // the group no longer exists: must not throw
  await listeners.button('something-else', 0);
});

// Value: protects=in ask mode a full regroup over existing groups changes nothing until the user presses Regroup, and Keep leaves every group as it was;
//   fails_when=groups are dissolved before the answer, the Keep button applies the plan, or the parked plan is lost or applied twice;
//   why_new=every other full-regroup test runs with the question switched off; seam=none;
//   no_claim=that Chrome keeps session storage and delivers the click after stopping the worker (both are fakes here)
test('in ask mode a full regroup waits for the notification answer', async () => {
  for (const [button, expected] of [[1, [7, 7, NONE, NONE]], [0, null]]) {
    reset();
    settings = {}; // the default is 'ask'
    stubAI({ groups: [{ name: 'Docs', tabs: [0, 2] }, { name: 'Dev', tabs: [1, 3] }] });
    await click();
    const [, id, options] = calls.find((c) => c[0] === 'notify');
    assert.match(options.message, /Docs, Dev/);
    assert.deepEqual(ungroupCalls(), []);
    assert.deepEqual([1, 2, 3, 4].map(groupOf), [7, 7, NONE, NONE]);

    await listeners.button(id, button);
    if (expected) {
      assert.deepEqual([1, 2, 3, 4].map(groupOf), expected);
    } else {
      assert.equal(titleOf(1), 'Docs');
      assert.equal(groupOf(1), groupOf(3));
      assert.equal(titleOf(2), 'Dev');
    }
    const before = ungroupCalls().length;
    await listeners.button(id, 0); // a second press finds no parked plan
    assert.equal(ungroupCalls().length, before);
  }

  // With no existing group there is nothing to replace, so nothing is asked.
  reset();
  settings = {};
  tabs = [tab(3), tab(4)];
  stubAI({ groups: [{ name: 'Dev', tabs: [0, 1] }] });
  await click();
  assert.equal(calls.filter((c) => c[0] === 'notify').length, 0);
  assert.equal(titleOf(3), 'Dev');
});

// Value: protects=a Regroup answer given after the window changed, or after 5 minutes, dissolves nothing; closing the question drops the parked plan;
//   fails_when=the parked plan is applied without checking the layout or its age, or a dismissed plan stays in session storage;
//   why_new=four reviewers found the old plan could dissolve groups made after the question; seam=Date.now is mocked for the age check;
//   no_claim=when Chrome fires onClosed for a timed-out notification (the event is fired by hand)
test('a stale Regroup answer changes nothing', async (t) => {
  t.mock.method(console, 'error', () => {});
  const ask = async () => {
    reset();
    settings = {};
    stubAI({ groups: [{ name: 'Docs', tabs: [0, 2] }, { name: 'Dev', tabs: [1, 3] }] });
    await click();
    return calls.find((c) => c[0] === 'notify')[1];
  };

  // The user made a new group after the question.
  let id = await ask();
  groups.push({ id: 42, title: 'Later', collapsed: true });
  tabs.find((t) => t.id === 3).groupId = 42;
  await listeners.button(id, 0);
  assert.deepEqual(ungroupCalls(), []);
  assert.equal(groupOf(3), 42);
  assert.equal(lastBadge(), '!');
  assert.match(calls.filter((c) => c[0] === 'title').at(-1)[1], /changed after the question/);

  // Nothing changed, but the answer came too late.
  id = await ask();
  const now = Date.now();
  t.mock.method(Date, 'now', () => now + 6 * 60000);
  await listeners.button(id, 0);
  assert.deepEqual(ungroupCalls(), []);
  assert.equal(lastBadge(), '!');
  assert.match(calls.filter((c) => c[0] === 'title').at(-1)[1], /expired/);
  t.mock.restoreAll();
  t.mock.method(console, 'error', () => {});

  // A good answer applies the plan and clears an old "!" badge.
  id = await ask();
  calls.push(['badge', '!']);
  await listeners.button(id, 0);
  assert.equal(titleOf(1), 'Docs');
  assert.equal(lastBadge(), '');

  // Closing the question drops the parked plan, and a late Regroup press then says so.
  id = await ask();
  listeners.closed(id);
  assert.equal(id in session, false);
  await listeners.button(id, 0);
  assert.deepEqual(ungroupCalls(), []);
  assert.equal(lastBadge(), '!');
});

// Value: protects=when the dissolve fails after the Regroup button is pressed, the question is closed, the "!" badge shows the reason and no group is lost;
//   fails_when=the button handler drops its error handler, so a failed regroup from a notification is silent;
//   why_new=the ask-mode test only presses the buttons on a plan that applies cleanly; seam=none;
//   no_claim=which errors real Chrome raises while a tab is dragged (tabs.ungroup is made to reject by hand)
test('a regroup that fails after the Regroup button shows the "!" badge', async (t) => {
  t.mock.method(console, 'error', () => {});
  reset();
  settings = {}; // the default is 'ask'
  stubAI({ groups: [{ name: 'Docs', tabs: [0, 2] }, { name: 'Dev', tabs: [1, 3] }] });
  await click();
  const [, id] = calls.find((c) => c[0] === 'notify');
  t.mock.method(chrome.tabs, 'ungroup', async () => {
    throw new Error('Tabs cannot be edited right now');
  });

  await listeners.button(id, 0);
  assert.deepEqual(calls.filter((c) => c[0] === 'clearNotification'), [['clearNotification', id]]);
  assert.equal(lastBadge(), '!');
  assert.match(calls.filter((c) => c[0] === 'title').at(-1)[1], /cannot be edited/);
  assert.deepEqual([1, 2, 3, 4].map(groupOf), [7, 7, NONE, NONE]);
});

// Value: protects=a group Chrome refuses to make is skipped and the other groups in the plan are still made, with no error badge;
//   fails_when=the per-group error handling is lost, so one refused group aborts the rest of the plan;
//   why_new=no test makes tabs.group reject; seam=none;
//   no_claim=when real Chrome refuses a group (tabs.group is made to reject for one tab by hand)
test('one group Chrome refuses does not stop the others', async (t) => {
  t.mock.method(console, 'warn', () => {});
  reset();
  const group = chrome.tabs.group;
  t.mock.method(chrome.tabs, 'group', async (args) => {
    if (args.tabIds.includes(1)) throw new Error('Tabs cannot be edited right now');
    return group(args);
  });
  stubAI({ groups: [{ name: 'Docs', tabs: [0, 1] }, { name: 'Dev', tabs: [2, 3] }] });
  await click();
  assert.equal(groupOf(1), NONE);
  assert.equal(titleOf(3), 'Dev');
  assert.equal(groupOf(3), groupOf(4));
  assert.equal(lastBadge(), '');
});

// Value: protects=a toolbar click made while an automatic run is in flight is kept and runs as a full regroup right after it;
//   fails_when=the "ignore a second click" rule is widened to every busy window, so a click during an automatic run is lost;
//   why_new=the double-click test only covers a click during a full run; seam=none;
//   no_claim=real timing between Chrome events (the click is fired inside the fetch stub)
test('a click during an automatic run is not lost: the full regroup runs next', async () => {
  reset();
  const fresh = tab(3, NONE, { title: 'Queued round' });
  tabs = [tab(1, 7), tab(2, 7), fresh, tab(4)];
  let clicked = false;
  const prompts = stubAI({ groups: [{ name: 'Dev', tabs: [0, 1] }] }, { whileWaiting: () => clicked || ((clicked = true), click()) });
  await loadTab(fresh);
  await new Promise((resolve) => setImmediate(resolve)); // let the queued full run finish

  assert.equal(prompts.length, 2);
  assert.match(prompts[1], /^Existing groups: \[\]\nTabs:\n0 \| Tab 1 /);
  assert.equal(ungroupCalls().length, 1);
  assert.equal(titleOf(1), 'Dev');
  assert.equal(groupOf(1), groupOf(2));
  assert.equal(groupOf(3), NONE);
});

// Value: protects=a click with no API key opens the options page, calls no AI, changes nothing, and the next click works;
//   fails_when=the missing-key return leaves the window marked busy, or stops opening the options page;
//   why_new=every other test runs with a key set; seam=none;
