// Value: protects=the manifest grants the notifications permission, ships the icon the notifications ask for, and binds Alt+Shift+G to the toolbar action;
//   fails_when=the permission is dropped (the worker then fails at load), the icon file is missing or renamed, or the shortcut is removed;
//   why_new=no test reads manifest.json; seam=none;
//   no_claim=that Chrome accepts the manifest or that the icon is committed (the file is only checked on disk)
test('the manifest grants what the notifications and the shortcut need', async () => {
  const root = new URL('../', import.meta.url);
  const manifest = JSON.parse(readFileSync(new URL('manifest.json', root), 'utf8'));
  assert.ok(manifest.permissions.includes('notifications'));
  assert.equal(manifest.commands._execute_action.suggested_key.default, 'Alt+Shift+G');

  reset();
  settings = {}; // 'ask', so a click over the existing group shows a notification
  stubAI({ groups: [{ name: 'Dev', tabs: [0, 1] }] });
  await click();
  const [, , options] = calls.find((c) => c[0] === 'notify');
  assert.ok(existsSync(new URL(options.iconUrl, root)), options.iconUrl);
  assert.ok(existsSync(new URL(manifest.icons['128'], root)));
});
